class PolicyResponse(ManagementModel):
    """`GET` response: the stored policy plus the unknown-AAGUID action it
    currently *resolves to*.

    `unknown_aaguid` is nullable, where `null` means "use this mode's
    default" (deny under `direct_required`, allow otherwise). A client that
    only saw the stored `null` would have to re-derive that rule itself to
    display what the policy actually does — and a security rule implemented
    twice is a security rule that will eventually disagree with itself. So
    the server resolves it once, here, and reports both: the admin's stored
    intent and its effect.
    """

    _OPEN_ENUM_FIELDS: ClassVar[dict[str, frozenset[str]]] = {
        "effective_unknown_aaguid": frozenset({"allow", "deny"}),
        "min_certification": frozenset({"L1", "L1Plus", "L2", "L2Plus", "L3", "L3Plus"}),
        "mode": frozenset({"none", "indirect", "direct_required"}),
        "unknown_aaguid": frozenset({"allow", "deny"}),
    }
    """The open enums among this model's fields and the values this SDK knows:

    an unknown value decodes, and :meth:`to_wire` refuses to send it
    (CONTRACT §29.2, §32.2).
    """

    allowed_aaguids: list[str] | None = None
    """`None` = every AAGUID is allowed except `blocked_aaguids`.


    `Some(vec![])` is a deliberate "nothing may register" policy and is
    accepted as such: `evaluate` denies every AAGUID against an empty
    allow-list. Nothing rejects it, precisely because the failure direction
    is safe — a client that sends `[]` when it meant `null` gets a
    locked-down tenant, which is visible immediately, rather than an open
    one, which is not.
    """

    block_revoked_status: bool
    """Deny registration if the MDS entry has ever reported `REVOKED` or any

    `*_COMPROMISE` status (sticky — D8 step 7).
    """

    blocked_aaguids: list[str] | None = None
    """``blocked_aaguids``."""

    effective_unknown_aaguid: UnknownAaguidAction
    """The action actually applied to an AAGUID with no MDS metadata, with

    `unknown_aaguid: null` resolved against `mode`. Read-only — `PUT`
    ignores it.
    """

    min_certification: CertificationLevel | None = None
    """``min_certification``."""

    mode: AttestationMode
    """``mode``."""

    require_fido_certified: bool
    """Require *some* `FIDO_CERTIFIED*` status, any level. Independent of (and

    checked before) `min_certification`.
    """

    unknown_aaguid: UnknownAaguidAction | None = None
    """``unknown_aaguid``."""


class PrivacyPolicy(ManagementModel):
    """Data-retention rules that apply after a subject asks to be erased."""

    deletion_grace_period_days: int
    """How long a requested account erasure stays cancellable before the purge

    runs, in days.

    The window exists so an erasure triggered by mistake, or under coercion,
    can be undone — `POST /api/v1/auth/account/delete/cancel` works for
    exactly this long. It was fixed at 30 days in the handler, which meant
    the "cancel a pending deletion" control in the admin UI referred to a
    duration no operator could see or change.

    Shorter is the more restrictive direction, so a tenant may lower it and
    not raise it: it is time spent holding data the subject has already
    asked to have erased, and GDPR Art. 17(1) asks for that to be "without
    undue delay". The upper bound of 90 days is where Art. 12(3)'s one-month
    response deadline plus its two-month extension for complex cases runs
    out; anything past 30 wants a reason recorded.
    """


